+const navToggle = document.querySelector(".nav-toggle");
+const primaryNav = document.querySelector("#primary-navigation");
+const navLinks = primaryNav.querySelectorAll("a");
+const cartButton = document.querySelector(".cart-button");
+const cartCount = document.querySelector(".cart-count");
+const addToCartButtons = document.querySelectorAll(".add-to-cart");
+const toast = document.querySelector(".toast");
+const newsletterForm = document.querySelector(".newsletter-form");
+const emailInput = document.querySelector("#email");
+const emailError = document.querySelector("#email-error");
+
+let cartTotal = 0;
+let toastTimer;
+
+function setNavigationState(isOpen) {
+  navToggle.setAttribute("aria-expanded", String(isOpen));
+  primaryNav.classList.toggle("is-open", isOpen);
+  document.body.classList.toggle("nav-open", isOpen);
+}
+
+function showToast(message) {
+  window.clearTimeout(toastTimer);
+  toast.textContent = message;
+  toast.classList.add("is-visible");
+
+  toastTimer = window.setTimeout(() => {
+    toast.classList.remove("is-visible");
+  }, 3200);
+}
+
+navToggle.addEventListener("click", () => {
+  const isOpen = navToggle.getAttribute("aria-expanded") === "true";
+  setNavigationState(!isOpen);
+});
+
+navLinks.forEach((link) => {
+  link.addEventListener("click", () => setNavigationState(false));
+});
+
+document.addEventListener("keydown", (event) => {
+  if (event.key === "Escape" && navToggle.getAttribute("aria-expanded") === "true") {
+    setNavigationState(false);
+    navToggle.focus();
+  }
+});
+
+addToCartButtons.forEach((button) => {
+  button.addEventListener("click", () => {
+    const productName = button.dataset.product;
+    cartTotal += 1;
+    cartCount.textContent = String(cartTotal);
+    cartButton.setAttribute("aria-label", `Cart, ${cartTotal} ${cartTotal === 1 ? "item" : "items"}`);
+    showToast(`${productName} added to cart. Cart now has ${cartTotal} ${cartTotal === 1 ? "item" : "items"}.`);
+  });
+});
+
+newsletterForm.addEventListener("submit", (event) => {
+  event.preventDefault();
+
+  if (!emailInput.validity.valid) {
+    emailInput.setAttribute("aria-invalid", "true");
+    emailError.textContent = "Enter a valid email address to sign up.";
+    emailInput.focus();
+    return;
+  }
+
+  emailInput.removeAttribute("aria-invalid");
+  emailError.textContent = "";
+  newsletterForm.reset();
+  showToast("Thanks for signing up for Northline Goods updates.");
+});
+
+emailInput.addEventListener("input", () => {
+  if (emailInput.validity.valid) {
+    emailInput.removeAttribute("aria-invalid");
+    emailError.textContent = "";
+  }
+});
+

')

